import { CONTRACT_FINGERPRINT } from "@ine/contracts";

/**
 * Fingerprint generated by the current Back-end branch after building its
 * contract package. The frontend keeps its neutral internal vocabulary and
 * adapts the two known legacy wire differences only at the HTTP boundary.
 */
export const BRYAN_BACKEND_CONTRACT_FINGERPRINT =
  "1d5ca770e9c1e26dd437e04038a70477d3498b64a27f886eb0f1667b4b9976e5" as const;

const supportedBackendFingerprints = new Set<string>([
  CONTRACT_FINGERPRINT,
  BRYAN_BACKEND_CONTRACT_FINGERPRINT,
]);

const inboundSemanticStates: Readonly<Record<string, string>> = {
  "financial.positive": "trend.increase",
  "financial.negative": "trend.decrease",
  "financial.neutral": "evidence.neutral",
  "financial.warning": "evidence.caution",
};

const outboundSemanticStates: Readonly<Record<string, string>> = {
  "trend.increase": "financial.positive",
  "trend.decrease": "financial.negative",
  "evidence.neutral": "financial.neutral",
  "evidence.caution": "financial.warning",
};

type AdaptDirection = "from-backend" | "to-backend";
const MAX_ADAPTER_DEPTH = 64;
const MAX_ADAPTER_VALUES = 50_000;

interface AdapterBudget {
  remaining: number;
}

export function isSupportedBackendContractFingerprint(fingerprint: string) {
  return supportedBackendFingerprints.has(fingerprint);
}

/** Converts a known backend wire payload to the frontend's neutral vocabulary. */
export function normalizeBackendContractPayload(value: unknown): unknown {
  return adaptContractValue(value, "from-backend", 0, { remaining: MAX_ADAPTER_VALUES });
}

/** Converts a frontend request, including currentSpecification, to the backend wire vocabulary. */
export function normalizeFrontendContractPayloadForBackend(value: unknown): unknown {
  return adaptContractValue(value, "to-backend", 0, { remaining: MAX_ADAPTER_VALUES });
}

function adaptContractValue(
  value: unknown,
  direction: AdaptDirection,
  depth: number,
  budget: AdapterBudget,
): unknown {
  if (depth > MAX_ADAPTER_DEPTH || budget.remaining <= 0) return value;
  budget.remaining -= 1;

  if (Array.isArray(value)) {
    return value.map((item) => adaptContractValue(item, direction, depth + 1, budget));
  }
  if (!isPlainRecord(value)) return value;

  const entries = Object.entries(value).map(([key, child]): [string, unknown] => {
    if (key === "semanticState" && typeof child === "string") {
      const states = direction === "from-backend" ? inboundSemanticStates : outboundSemanticStates;
      return [key, states[child] ?? child];
    }
    return [key, adaptContractValue(child, direction, depth + 1, budget)];
  });
  const adapted = Object.fromEntries(entries) as Record<string, unknown>;

  if (direction === "to-backend" && adapted.type === "visualization" && isPlainRecord(adapted.encoding)) {
    adapted.encoding = stripUnsupportedVisualizationFormats(adapted.encoding);
  }

  return adapted;
}

function stripUnsupportedVisualizationFormats(encoding: Record<string, unknown>) {
  return Object.fromEntries(Object.entries(encoding).map(([channelName, channel]) => {
    if (!isPlainRecord(channel) || !("format" in channel)) return [channelName, channel];
    const { format: _format, ...backendChannel } = channel;
    return [channelName, backendChannel];
  }));
}

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}
